contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public payable {
        require(!c.isAdmin(address(this)));

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}
